const data = {"volume": {"Chest": 65754.0, "Back": 85021.0, "Legs": 3180.0, "Arms": 45873.5, "Shoulders": 7895.5, "Core": 0, "Other": 15153.0}, "recovery": {"Chest": 79.3, "Back": 79.3, "Legs": 79.3, "Arms": 79.3, "Shoulders": 79.3, "Core": 100}, "predicted": {"Chest": "Ready in ~10h (01:58)", "Back": "Ready in ~10h (01:58)", "Legs": "Ready in ~10h (01:58)", "Arms": "Ready in ~10h (01:58)", "Shoulders": "Ready in ~10h (01:58)", "Core": "Fully Recovered"}, "whoop_global": 31.0, "daily_vol": {"2026-01-30": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-29": {"Chest": 10251.5, "Back": 12440.0, "Legs": 0, "Arms": 4682.0, "Shoulders": 1387.5, "Core": 0, "Other": 0}, "2026-01-27": {"Chest": 4567.5, "Back": 9339.5, "Legs": 0, "Arms": 2618.0, "Shoulders": 805.0, "Core": 0, "Other": 4684.5}, "2026-01-26": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-25": {"Chest": 14562.0, "Back": 0, "Legs": 0, "Arms": 0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-24": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-23": {"Chest": 7211.0, "Back": 16320.0, "Legs": 0, "Arms": 2362.0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-22": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 12465.0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-18": {"Chest": 0, "Back": 9535.0, "Legs": 0, "Arms": 1017.0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-16": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 12002.0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-13": {"Chest": 6653.0, "Back": 4750.0, "Legs": 368.0, "Arms": 0, "Shoulders": 885.0, "Core": 0, "Other": 0}, "2026-01-11": {"Chest": 12283.0, "Back": 12510.5, "Legs": 2812.0, "Arms": 4506.5, "Shoulders": 4138.5, "Core": 0, "Other": 5231.0}, "2026-01-09": {"Chest": 0, "Back": 0, "Legs": 0, "Arms": 2293.0, "Shoulders": 0, "Core": 0, "Other": 0}, "2026-01-07": {"Chest": 3016.5, "Back": 9188.5, "Legs": 0, "Arms": 2576.0, "Shoulders": 679.5, "Core": 0, "Other": 5237.5}, "2026-01-06": {"Chest": 7209.5, "Back": 10937.5, "Legs": 0, "Arms": 1352.0, "Shoulders": 0, "Core": 0, "Other": 0}}, "nutrition": [{"date": "2026-01-30", "kcal": 0, "protein": 0}, {"date": "2026-01-31", "kcal": 3835.0, "protein": 290.0}], "overload": {"Kneeling Dual-Handle Lat Pulldown": [{"date": "2026-01-06", "vol": 3597.5}, {"date": "2026-01-07", "vol": 3598.5}, {"date": "2026-01-11", "vol": 3612.0}, {"date": "2026-01-23", "vol": 3687.0}, {"date": "2026-01-27", "vol": 3688.0}, {"date": "2026-01-29", "vol": 3879.5}], "Standing Barbell Triceps Push Down": [{"date": "2026-01-07", "vol": 2576.0}, {"date": "2026-01-09", "vol": 1161.0}, {"date": "2026-01-11", "vol": 2627.0}, {"date": "2026-01-16", "vol": 2355.0}, {"date": "2026-01-22", "vol": 2631.0}, {"date": "2026-01-27", "vol": 2618.0}, {"date": "2026-01-29", "vol": 1146.0}], "Kneeling Single-Arm Lat Pulldown": [{"date": "2026-01-06", "vol": 4293.0}, {"date": "2026-01-23", "vol": 4211.5}, {"date": "2026-01-29", "vol": 3891.5}], "Kneeling Dual-Handle Underhand Lat Pulldown": [{"date": "2026-01-07", "vol": 3735.0}, {"date": "2026-01-11", "vol": 3745.5}, {"date": "2026-01-27", "vol": 3809.5}], "Standing High-to-Low Woodchops": [{"date": "2026-01-07", "vol": 3617.0}, {"date": "2026-01-11", "vol": 3623.0}, {"date": "2026-01-27", "vol": 3076.5}]}, "last_updated": "2026-02-01 16:01:22"};

        document.getElementById('date-updated').innerText = `TS: ${data.last_updated} | V3.0-FINAL`;
        document.getElementById('whoop-score').innerText = data.whoop_global || '--';

        // Set Load Distribution Date Range
        const allVolDates = Object.keys(data.daily_vol).filter(d => Object.values(data.daily_vol[d]).some(v => v > 0)).sort();
        if (allVolDates.length > 0) {
            const start = new Date(allVolDates[0] + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
            const end = new Date(allVolDates[allVolDates.length - 1] + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'});
            document.getElementById('volume-range').innerText = `(${start} - ${end})`;
        }

        // Predictions
        const predList = document.getElementById('prediction-list');
        for (const [part, msg] of Object.entries(data.predicted)) {
            if (msg.includes('Fully')) continue;
            predList.innerHTML += `
                <div class="prediction-item">
                    <div class="part">${part}</div>
                    <div class="time">${msg}</div>
                </div>
            `;
        }

        // Volume List & Body Color
        const volumeList = document.getElementById('volume-list');
        const maxVol = Math.max(...Object.values(data.volume));

        // Calculate last trained dates
        const lastTrained = {};
        Object.keys(data.volume).forEach(part => {
            const dates = Object.keys(data.daily_vol)
                .filter(d => data.daily_vol[d][part] > 0)
                .sort();
            lastTrained[part] = dates.length > 0 ? dates[dates.length - 1] : 'Never';
        });

        for (const [part, vol] of Object.entries(data.volume)) {
            if (part === 'Other' || vol === 0) continue;
            const percentage = (vol / maxVol) * 100;
            const date = lastTrained[part];
            const dateDisplay = date !== 'Never' ? new Date(date + 'T12:00:00').toLocaleDateString('en-US', {month: 'short', day: 'numeric'}) : 'N/A';

            volumeList.innerHTML += `
                <div class="muscle-label">
                    <span>${part} <span style="font-size: 0.8em; color: #444; margin-left: 8px;">Last: ${dateDisplay}</span></span>
                    <span><b>${vol.toLocaleString()}</b> lbs</span>
                </div>
                <div class="volume-bar">
                    <div class="volume-fill" style="width: ${percentage}%"></div>
                </div>
            `;
            const score = data.recovery[part] || 100;
            let color = '#00ff88';
            if (score < 40) color = '#ff4444';
            else if (score < 70) color = '#ffbb00';

            const ids = part === 'Arms' ? ['part-Arms-L', 'part-Arms-R'] : (part === 'Legs' ? ['part-Legs-L', 'part-Legs-R'] : [`part-${part}`]);
            ids.forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    el.style.fill = color;
                    if (score < 100) el.setAttribute('filter', 'url(#glow)');
                }
            });
        }

        // Overload Chart
        const overloadCtx = document.getElementById('overloadChart').getContext('2d');
        const overloadBadges = document.getElementById('overload-badges');

        // 1. Unified X-Axis: Collect and sort all unique dates
        const allDates = new Set();
        Object.values(data.overload).forEach(exData => {
            exData.forEach(d => allDates.add(d.date));
        });
        const sortedLabels = Array.from(allDates).sort();

        // 2. Expand Scope: Top 5 exercises
        const exerciseNames = Object.keys(data.overload).slice(0, 5);
        const colors = ['#00ff88', '#00ccff', '#ff00ff', '#ffff00', '#ff8800'];

        const datasets = exerciseNames.map((ex, i) => {
            // Map data to the unified labels array (null for missing dates)
            const chartData = sortedLabels.map(date => {
                const found = data.overload[ex].find(d => d.date === date);
                return found ? found.vol : null;
            });

            return {
                label: ex,
                data: chartData,
                borderColor: colors[i],
                backgroundColor: colors[i],
                borderWidth: 2,
                tension: 0.4,
                pointRadius: 3,
                pointHoverRadius: 6,
                spanGaps: true // Connect points even if dates are missing
            };
        });

        new Chart(overloadCtx, {
            type: 'line',
            data: { 
                labels: sortedLabels,
                datasets: datasets 
            },
            options: { 
                responsive: true, 
                maintainAspectRatio: false,
                interaction: {
                    intersect: false,
                    mode: 'index',
                },
                scales: { 
                    y: { 
                        display: true,
                        grid: { color: '#111', drawBorder: false },
                        ticks: { 
                            color: '#555', 
                            font: { size: 10 },
                            callback: (val) => (val >= 1000 ? (val / 1000).toFixed(1) + 'k' : val)
                        }
                    }, 
                    x: { 
                        grid: { display: false }, 
                        ticks: { color: '#444', font: { size: 9 }, maxRotation: 45, minRotation: 45 } 
                    } 
                },
                plugins: { 
                    legend: { 
                        display: true, 
                        position: 'top',
                        align: 'start',
                        labels: {
                            color: '#888',
                            boxWidth: 10,
                            font: { size: 10 },
                            padding: 10
                        }
                    },
                    tooltip: {
                        backgroundColor: '#0a0a0a',
                        titleColor: '#00ff88',
                        bodyColor: '#fff',
                        borderColor: '#333',
                        borderWidth: 1,
                        padding: 10,
                        displayColors: true,
                        callbacks: {
                            label: (context) => ` ${context.dataset.label}: ${context.parsed.y.toLocaleString()} lbs`
                        }
                    }
                }
            }
        });

        // Nutrition Data
        if (data.nutrition && data.nutrition.length > 0) {
            const latest = data.nutrition[data.nutrition.length - 1];
            document.getElementById('nut-kcal').innerText = Math.round(latest.kcal);
            document.getElementById('nut-protein').innerText = Math.round(latest.protein) + 'g';
        }

        // Volume Trend
        const trendCtx = document.getElementById('volumeTrendChart').getContext('2d');
        const sortedDates = Object.keys(data.daily_vol).sort();
        new Chart(trendCtx, {
            type: 'bar',
            data: {
                labels: sortedDates.slice(-10),
                datasets: [{
                    data: sortedDates.slice(-10).map(d => Object.values(data.daily_vol[d]).reduce((a,b)=>a+b, 0)),
                    backgroundColor: '#111',
                    hoverBackgroundColor: '#00ff88',
                    borderRadius: 2
                }]
            },
            options: { 
                responsive: true, 
                maintainAspectRatio: false,
                scales: { y: { display: false }, x: { grid: { display: false }, ticks: { display: false } } },
                plugins: { legend: { display: false } }
            }
        });
